import { GoogleSpreadsheet } from 'google-spreadsheet';
import { JWT } from 'google-auth-library';
import credentials from '../../google-service-account.json';

export const updateGoogleSheet = async (rowIndex: number, entry: Entry) => {
  const serviceAccountAuth = new JWT({
    // env var values here are copied from service account credentials generated by google
    // see "Authentication" section in docs for more info
    email: credentials.client_email,
    key: credentials.private_key,
    scopes: ['https://www.googleapis.com/auth/spreadsheets'],
  });

  const doc = new GoogleSpreadsheet('1u3Z_-eD1AtncpZCrd0EEQTyFDni2AhSp2eId2w5lqog', serviceAccountAuth);
  await doc.loadInfo();

  const sheet = doc.sheetsById['1480154901']

  await sheet.loadCells(`A1:A${rowIndex}`);
  sheet.getCellByA1(`A${rowIndex}`).value = entry.filename;

  await sheet.saveUpdatedCells();
}
